// src/assets/favicon.js
import { ASSET_VERSION } from '../config/constants.js';
// Self-hosted brand assets: the JobForion "TF" logo mark, embedded as
// base64 raster at every size a browser/OS asks for — favicon.svg wraps
// the same raster in a tiny SVG shell so it still serves valid
// image/svg+xml (keeps every existing <link>/<img> reference working
// unchanged; nothing outside this file needs to know it's a PNG inside).
//
// BACKGROUND HANDLING (per-asset, not one-size-fits-all):
//  • favicon.svg / favicon.ico / favicon-32.png / favicon-16.png →
//    TRANSPARENT corners. This is the standard favicon convention:
//    browser tabs and OS chrome supply their own background, so a
//    transparent-cornered mark blends in on light or dark UI alike.
//  • apple-touch-icon.png / icon-512.png → OPAQUE, corners filled solid
//    black. iOS ignores/mishandles alpha on home-screen icons (renders
//    transparency as black anyway), and Android/PWA "maskable" icons
//    (manifest.js sets purpose: "any maskable" on icon-512) must be
//    fully opaque since the OS crops its own shape over them. icon-512
//    is also reused as the og:image / schema.org Organization logo, where
//    a solid square renders predictably across every social platform —
//    transparency there is a gamble on whatever canvas color each
//    platform happens to composite onto.
//
// ── FAVICON / BRAND ASSETS (self-hosted, no external deps) ───────
export const FAVICON_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><image href="data:image/png;base64," width="64" height="64"/></svg>`;
export const FAVICON_ICO_B64 = "";
export const FAVICON_32_B64 = "";
export const FAVICON_16_B64 = "";
export const APPLE_TOUCH_B64 = "";
export const ICON512_B64 = "";

export function b64ToBytes(b64) {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

// Every href is cache-busted with ASSET_VERSION (see config/constants.js)
// so a logo/icon update reaches every device immediately instead of
// waiting out each asset's long Cache-Control lifetime.
export const ICON_HEAD = `
<link rel="icon" href="/favicon.svg?v=${ASSET_VERSION}" type="image/svg+xml">
<link rel="icon" href="/favicon-32.png?v=${ASSET_VERSION}" sizes="32x32" type="image/png">
<link rel="icon" href="/favicon-16.png?v=${ASSET_VERSION}" sizes="16x16" type="image/png">
<link rel="shortcut icon" href="/favicon.ico?v=${ASSET_VERSION}">
<link rel="apple-touch-icon" href="/apple-touch-icon.png?v=${ASSET_VERSION}">
<link rel="manifest" href="/manifest.json?v=${ASSET_VERSION}">
<meta name="theme-color" content="#3556FF">`;
